function weapons(){for(const [id,key]of [['labCatalogMain','catalogMainId'],['labCatalogOff','catalogOffId']]){const select=el(id);select.replaceChildren(new Option('ใช้ชุดฝึก / ค่าจำลองของสถานการณ์',''));for(const r of rows().filter(r=>r.kind==='weapon'&&r.enabled!==false)){try{const w=DecideCatalogEquipment.weapon(r);if(N.classes[plan.job].weapons.includes(w.type)&&(id==='labCatalogMain'||w.hands===1))select.add(new Option(r.displayName||r.name,r.id));}catch{}}select.value=plan[key]||'';}el('labWeapon').replaceChildren();for(const w of Object.values(N.weapons).filter(w=>N.classes[plan.job].weapons.includes(w.type)))el('labWeapon').add(new Option(w.name,w.id));el('labWeapon').value=plan.weapon;offhands();}
